import{_ as n,l as i,o as e,c as l,v as o,p as s,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"内生增长：人力资本与 R&D","description":"","frontmatter":{"title":"内生增长：人力资本与 R&D","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/endogenous-growth.md","filePath":"econ/endogenous-growth.md","lastUpdated":1789023840000}'),A={name:"econ/endogenous-growth.md"};function E(c,a,m,u,g,_){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="内生增长-人力资本与-r-d" tabindex="-1">内生增长：人力资本与 R&amp;D <a class="header-anchor" href="#内生增长-人力资本与-r-d" aria-label="Permalink to &quot;内生增长：人力资本与 R&amp;D&quot;">​</a></h1><div class="epigraph"><p>若知识可以积累且报酬不递减到零，长期增长率就不再是模型外的 $g$，而由研发与人力资本的资源配置决定。</p><footer>—— Romer, Increasing Returns and Long-Run Growth, JPE 1986；Endogenous Technological Change, JPE 1990；对照 Lucas, JME 1988</footer></div><p><a href="/econ/olg-diamond">上一课</a>（OLG 与动态无效率再访）。在外生 \\(g\\) 下选资本密度。黄金律与修正黄金律都把人均增长当成技术的礼物。本课的缺口是：\\(A\\) 若也是生产出来的，递减报酬还能否关掉增长引擎。Romer 与 Lucas 给出两条主干：知识溢出与人力资本积累；Romer 1990 再把研发写成故意的垄断竞争。收敛核算是下一课对跨国含义的缺口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>索洛里 \\(\\dot{A}/A=g\\) 给定。经验上研发支出、教育年限与增长相关，模型却无法让政策进入 \\(g\\)。若把 \\(A\\) 写成 rival 的普通资本，报酬递减会把它送回索洛稳态。缺口是找到一种<strong>非竞争</strong>的知识：一人使用不妨碍另一人，从而社会报酬可以递增。</p><p>Lucas（1988）让人力资本 \\(h\\) 靠学习时间积累，人均产出可以随 \\(h\\) 永续增长。Romer（1986）让知识作为生产的副产品溢出。Romer（1990）把新品种中间品的发明写成研发部门，增长取决于研发劳动力份额与专利带来的垄断租。本课钉结构，不估计跨国回归。</p><p><span class="marginnote">AK 模型 \\(Y=AK\\) 是刀刃：资本报酬恰好恒定。它可以当教学极限，不是经验上「资本份额为 1」。Romer 的要点是知识的非竞争性，不是把 \\(K\\) 改名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>知识运动的示意：\\(\\dot{A}=\\eta L_A A^\\phi\\)。\\(\\phi=1\\) 时增长率与研发规模成正比，有强规模效应；\\(\\phi\\lt 1\\) 时需要人口增长才能维持 \\(\\dot{A}/A\\) 不掉到零（半内生）。产品种类扩张使最终产品部门看起来像报酬递增，但每种中间品的生产仍可有递减。</p><p>人力资本：\\(\\dot{h}=h\\cdot u\\cdot \\psi\\)，学习时间 \\(u\\) 牺牲当前生产，换未来 \\(h\\)。平衡增长路径上消费、产出、\\(h\\) 同速。教育政策改变 \\(u\\)，从而改变增长率——这是对索洛「\\(s\\) 只改水平」的翻转，前提是积累对象没有递减到零。</p>',10)),(e(),s(h,null,{default:t(()=>[p(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SOLOW%5B%22%E7%B4%A2%E6%B4%9B%E5%A4%96%E7%94%9F%20g%22%5D%20--%3E%20ROMER%5B%22%E7%9F%A5%E8%AF%86%E9%9D%9E%E7%AB%9E%E4%BA%89%22%5D%0A%20%20ROMER%20--%3E%20SPILL%5B%22%E6%BA%A2%E5%87%BA%EF%BC%9ARomer%201986%22%5D%0A%20%20ROMER%20--%3E%20RD%5B%22%E7%A0%94%E5%8F%91%E5%93%81%E7%A7%8D%EF%BC%9ARomer%201990%22%5D%0A%20%20ROMER%20--%3E%20H%5B%22%E4%BA%BA%E5%8A%9B%E8%B5%84%E6%9C%AC%EF%BC%9ALucas%201988%22%5D%0A%20%20RD%20--%3E%20G%5B%22%E5%9D%87%E8%A1%A1%E5%A2%9E%E9%95%BF%E7%8E%87%E5%86%85%E7%94%9F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>社会最优研发通常大于分散均衡：溢出与垄断使私人回报低于社会回报。这是增长课里的市场失灵，与前面庇古税同一逻辑，对象换成知识。</p><h3 id="不要把内生增长写成「政策万能」" tabindex="-1">不要把内生增长写成「政策万能」 <a class="header-anchor" href="#不要把内生增长写成「政策万能」" aria-label="Permalink to &quot;不要把内生增长写成「政策万能」&quot;">​</a></h3><p>增长率对税率、专利长度、教育补贴敏感，是模型比较静态。把它读成发展中国家只要加一项补贴就能复制前沿 \\(g\\)，忽略了模仿、制度与 \\(A\\) 的可获得性。下一课用发展核算把 \\(K\\)、\\(h\\)、\\(A\\) 拆开。竞争性要素支付会耗尽产出，若仍有递增，知识不能按边际产品付酬——于是需要垄断或补贴。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>非竞争性使同一想法可以同时进入许多生产函数，社会生产可能对知识递增。竞争性要素支付会耗尽产出，若仍有递增，知识不能按边际产品付酬——于是需要垄断、补贴或公共研究。Romer 1990 用专利把租交给发明者，发明的激励与静态扭曲绑在一起。</p><p>平衡增长要求参数满足刀刃或人口配合，否则模型要么爆炸要么回到外生。这是理论代价：内生 \\(g\\) 换来了对规模与政策的强预测，经验上规模效应被质疑，才有半内生修正。本课保留「\\(g\\) 可被资源配置移动」这一句，细节版本留给文献。</p><p>黄金律在内生增长里要重写：计划者同时选消费、研发与教育时间，修正黄金律变成对知识影子价格的欧拉，而不只是 \\(f&#39;(k)=n+g+\\delta\\)。分散均衡的 \\(g\\) 通常低于计划者，因为溢出。专利长度在激励与垄断扭曲之间权衡，不是越长越好。</p><p><span class="marginnote">规模效应：人口越大，\\(L_A\\) 越大，\\(g\\) 越高。半内生把 \\(\\phi\\lt 1\\)，长期 \\(g\\) 仍跟人口增长走。经验上跨国 \\(g\\) 并不随人口线性上升，所以本课不把「加人」当增长政策。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>内生增长不解释短期失业，也不给货币角色。创新过程被写成平滑的 \\(\\dot{A}\\)，没有熊彼特式的企业微观结构。量化栏的价格发现与此无关。模仿与技术扩散可以使后发经济的 \\(A\\) 跳升，那是发展核算里 \\(A\\) 的水平，不是把索洛 \\(g\\) 再外生化一遍。</p><p>后课默认：长期人均增长可以来自 \\(h\\) 与研发，而不是只来自外生 \\(g\\)。下一课问各国水平差有多少是 \\(K\\)、多少是 \\(A\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>索洛的 \\(g\\) 外生；知识非竞争时增长可内生。</li><li>Lucas 走人力资本，Romer 走溢出与研发品种。</li><li>分散研发通常不足；专利是激励与扭曲的捆。</li><li>AK 是教学极限；规模效应在经验上要打折。</li><li>跨国水平分解是发展核算的缺口。</li><li>出处：Romer, JPE 1986 与 1990；Lucas, JME 1988。</li></ul>',13))])}const f=n(A,[["render",E]]);export{B as __pageData,f as default};
